from lfx.custom.custom_component.component import Component
from lfx.io import MessageInput, Output
from lfx.schema.message import Message

class FastSemanticRouter(Component):
    display_name = "Fast Semantic Router"
    description = "Analyzes user intent and routes the payload to the correct specialized agent."
    icon = "git-merge"
    name = "FastSemanticRouter"

    inputs = [
        MessageInput(name="user_input", display_name="User Input")
    ]

    outputs = [
        Output(display_name="To Scheduler Agent", name="scheduler_out", method="route_scheduler", group_outputs=True),
        Output(display_name="To Email Agent", name="email_out", method="route_email", group_outputs=True),
    ]

    def get_intent(self) -> str:
        text = self.user_input.text.lower()
        scheduler_keywords = ["book", "schedule", "meeting", "sync", "calendar", "availability", "time", "busy"]
        
        if any(word in text for word in scheduler_keywords):
            return "SCHEDULER"
        return "EMAIL" 

    def route_scheduler(self) -> Message:
        if self.get_intent() == "SCHEDULER":
            return self.user_input
        self.stop("scheduler_out") 
        return Message(text="")

    def route_email(self) -> Message:
        if self.get_intent() == "EMAIL":
            return self.user_input
        self.stop("email_out")
        return Message(text="")
